/**
 * Merge a per-session cloud override over the agent's static cloud config.
 *
 * Session-scoped `repos` / `env` / scalar flags win (so a channel can point
 * a cloud agent at a specific PR per session), and `envVars` are deep-merged
 * with the override taking precedence per key. Returns the defined side when
 * only one is present. Named fields keep base/override precedence explicit
 * at every call site.
 */
export function mergeCloudOptions(args) {
    const { base, override } = args;
    if (base === undefined) {
        return override;
    }
    if (override === undefined) {
        return base;
    }
    return {
        ...base,
        ...override,
        ...(base.envVars !== undefined || override.envVars !== undefined
            ? { envVars: { ...base.envVars, ...override.envVars } }
            : {}),
    };
}
/**
 * Session turn runtime. A per-session `cloud` attach forces cloud even when
 * the agent defaults to local.
 */
export function resolveSessionRuntime(args) {
    if (args.cloudOverride === undefined) {
        return args.agentRuntime;
    }
    return "cloud";
}
